@js:
const list = [];
const push = (title, url, size) => list.push({
  title: title,
  url: url,
  style: {layout_flexBasisPercent: size}
});

const xiuren = [["秀人网","2"],["美媛馆","5"],["波萝社","7"],["魅妍社","4"],["模范学院","3"],["优星馆","9"],["爱蜜社","6"],["嗲囡囡","11"],["顽味生活","13"],["蜜桃社","10"],["尤物馆","8"],["影私荟","12"],["星乐园","14"],["花の颜","15"],["薄荷叶","17"],["御女郎","16"],["糖果画报","19"],["尤蜜荟","18"],["模特联盟","20"],["猫萌榜","21"],["花漾show","22"],["星颜社","23"],["语画界","24"]];
const defaultTPL = "/forum-$id-{{page}}.html";

const orderMap = [["默认"],["最新","lastpost"],["推荐","heats"],["月榜","views","2592000"],["年榜","views","31536000"],["总榜","views"]]
const orderTPL = "/forum.php?mod=forumdisplay&fid=$id&filter=reply&orderby=$orderby&dateline=$dateline&page={{page}}";

const chars = orderMap.map(x=>x[0]);
list.push({
  "title": "排序",
  "type": "select",
  "action": "java.refreshExplore()",
  "chars": chars,
  "default": chars[0],
  "style": {"layout_flexBasisPercent": 1}
});
const order = String(infoMap.get("排序") || "默认");
const orderItem = orderMap.find(x => x[0] == order);
const [ , orderby, dateline] = orderItem;

xiuren.forEach(([title, id]) => {
  let url = dateline ? orderTPL.replace("$dateline", dateline).replace("$orderby", orderby).replace("$id", id) : orderby ? orderTPL.replace("&dateline=$dateline", "").replace("$orderby", orderby).replace("$id", id) : defaultTPL.replace("$id", id);
  push(title, url, 0.22)
})

infoMap.save();
JSON.stringify(list)

